    tokio::spawn(async move {
        let _ = axum::serve(listener, app).await;
    });

    let configured_model = "  configured-model  ";
    let normalized_configured_model = configured_model.trim();
    let mut h =
        AgentHarness::spawn_provider_with_max_sessions("databricks_v2", &host, configured_model, 2)
            .await;
    let initialize = h
        .send(
            "initialize",
            json!({ "protocolVersion": 1, "clientCapabilities": {} }),
        )
        .await;
    assert!(h.recv_for(initialize).await.get("result").is_some());

    for expected_attempts in [3, 6] {
        let request = h
            .send("session/new", json!({ "cwd": "/tmp", "mcpServers": [] }))
            .await;
        let response = h.recv_for(request).await;
        assert!(
            response["result"]["sessionId"].is_string(),
            "non-auth catalog failure blocked session creation: {response}"
        );
        assert_eq!(
            response["result"]["models"]["availableModels"],
            json!([{"modelId": normalized_configured_model, "name": normalized_configured_model}])
        );
        assert_eq!(attempts.load(Ordering::SeqCst), expected_attempts);
    }
}

#[tokio::test]
async fn rejected_static_token_does_not_consume_capacity_or_spawn_mcp() {
    use axum::http::StatusCode;

    let attempts = Arc::new(AtomicU64::new(0));
    let attempts_for_route = attempts.clone();
    let listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
    let host = format!("http://{}", listener.local_addr().unwrap());
    let app = Router::new().route(
        "/api/ai-gateway/v2/endpoints",
        get(move || {
            let attempts = attempts_for_route.clone();
            async move {
                if attempts.fetch_add(1, Ordering::SeqCst) == 0 {
                    Err((StatusCode::UNAUTHORIZED, "rejected"))
                } else {
                    Ok(Json(json!({
                        "endpoints": [{"name": "discovered-model"}],
                        "next_page_token": null,
                    })))
                }
            }
        }),
    );
    tokio::spawn(async move {
        let _ = axum::serve(listener, app).await;
    });

    let mut h = AgentHarness::spawn_provider("databricks_v2", &host, "discovered-model").await;
    let initialize = h
        .send(
            "initialize",
            json!({ "protocolVersion": 1, "clientCapabilities": {} }),
        )
        .await;
    assert!(h.recv_for(initialize).await.get("result").is_some());

    let pid_dir = TempDir::new().unwrap();
    let pid_file = pid_dir.path().join("mcp.pid");
    let fake_mcp = env!("CARGO_BIN_EXE_fake-mcp");
    let mcp_servers = json!([{
        "name": "must-not-spawn",
        "command": fake_mcp,
        "args": [],
        "env": [{
            "name": "FAKE_MCP_PID_FILE",
            "value": pid_file.to_string_lossy(),
        }],
    }]);

    let failed = h
        .send(
            "session/new",
            json!({ "cwd": "/tmp", "mcpServers": mcp_servers }),
        )
        .await;
    let failed_response = h.recv_for(failed).await;
    assert!(failed_response.get("error").is_some(), "{failed_response}");
    assert!(
        failed_response["error"]["message"]
            .as_str()
            .unwrap_or_default()
            .contains("llm auth"),
        "rejected static token did not retain auth semantics: {failed_response}"
    );
    tokio::time::sleep(Duration::from_millis(100)).await;
    assert!(
        !pid_file.exists(),
        "MCP process spawned before failed discovery was resolved"
    );

    let retry = h
        .send("session/new", json!({ "cwd": "/tmp", "mcpServers": [] }))
        .await;
    let retry_response = h.recv_for(retry).await;
    assert!(
        retry_response["result"]["sessionId"].is_string(),
        "failed discovery consumed the sole session slot: {retry_response}"
    );
    assert_eq!(attempts.load(Ordering::SeqCst), 2);
}

use super::*;

/// Feed `chunks` through a capture in order.
fn capture_of(chunks: &[&[u8]]) -> Capture {
    let capture = Capture::new();
    for chunk in chunks {
        capture.push(chunk);
    }
    capture
}

/// Render what the UI would show for a stream of `chunks`.
fn ui(chunks: &[&[u8]]) -> String {
    capture_of(chunks).ui()
}

// ── bounded capture ──────────────────────────────────────────────────────────

/// Output within the cap is passed through byte-for-byte — no marker, no loss.
#[test]
fn test_capture_leaves_short_output_untouched() {
    let short = "a".repeat(1536);

    assert_eq!(ui(&[short.as_bytes()]), short);
}

/// Over the cap, both ends survive and the middle is replaced by a marker
/// naming the omitted byte count — the head keeps the command's opening
/// context and the tail keeps the error that usually trails.
#[test]
fn test_capture_over_cap_keeps_head_and_tail_with_marker() {
    let input = format!(
        "{}{}{}",
        "H".repeat(512),
        "M".repeat(4000),
        "T".repeat(1024)
    );

    let out = ui(&[input.as_bytes()]);

    assert!(out.starts_with(&"H".repeat(512)));
    assert!(out.ends_with(&"T".repeat(1024)));
    assert!(
        out.contains("... (4000 bytes omitted) ..."),
        "marker must name the omitted byte count, got: {out}"
    );
}

/// The rendered result depends only on the byte stream, not on how the reads
/// happened to split it — a real drain sees arbitrary chunk sizes.
#[test]
fn test_capture_is_independent_of_chunk_boundaries() {
    let input = "x".repeat(9000);
    let one_shot = ui(&[input.as_bytes()]);

    let chunked: Vec<&[u8]> = input.as_bytes().chunks(7).collect();

    assert_eq!(ui(&chunked), one_shot);
}

/// Truncation must not split a multi-byte character. Both cut points land
/// mid-codepoint here; the partial bytes are dropped rather than decoded into
/// replacement chars.
#[test]
fn test_capture_does_not_split_multibyte_characters() {
    // "é" is 2 bytes, so every candidate cut index lands mid-character.
    let input = "é".repeat(4000);

    let out = ui(&[input.as_bytes()]);

    assert!(out.contains("bytes omitted"), "input must exceed the cap");
    assert!(!out.contains('\u{fffd}'), "no replacement chars: {out}");
}

/// Memory stays flat regardless of how much the installer prints: the rendered
/// UI result of a 4MiB stream is no larger than that of a 6KiB one.
#[test]
fn test_capture_of_huge_output_stays_bounded() {
    let chunk = vec![b'z'; 8192];

    let capture = Capture::new();
    for _ in 0..512 {
        capture.push(&chunk);
    }

    let out = capture.ui();
    assert!(
        out.len() < 2048,
        "4MiB of output must render bounded, got {} bytes",
        out.len()
    );
    assert!(out.contains("bytes omitted"));
}

// ── the log view is separately bounded ───────────────────────────────────────

/// The log view holds output the UI view had to cut. A toast is capped for
/// readability; the log file's budget is disk, and "Full log: {path}" has to
/// point at more than the toast already showed.
#[test]
fn test_log_view_keeps_output_the_ui_view_truncates() {
    let input = format!("start{}end", "m".repeat(64 * 1024));

    let capture = capture_of(&[input.as_bytes()]);

    assert!(
        capture.ui().contains("bytes omitted"),
        "64KiB must exceed the UI cap"
    );
    assert_eq!(
        capture.log(),
        input,
        "the same output must be complete in the log view"
    );
}

/// Even the log view is bounded — a runaway installer cannot fill the disk —
/// and when it does cut, the record says so inline at the cap rather than
/// implying completeness.
#[test]
fn test_log_view_is_bounded_and_marks_its_cap() {
    let head = "H".repeat(128 * 1024);
    let middle = "M".repeat(5000);
    let tail = "T".repeat(128 * 1024);
    let input = format!("{head}{middle}{tail}");

    let capture = capture_of(&[input.as_bytes()]);

    let out = capture.log();
    assert!(
        out.len() < 300 * 1024,
        "output past the log cap must render bounded, got {} bytes",
        out.len()
    );
    assert!(out.starts_with(&head), "the log head must survive intact");
    assert!(out.ends_with(&tail), "the log tail must survive intact");
    assert!(
        out.contains("... [5000 bytes omitted at cap] ..."),
        "a cut log record must name the cap inline, got the middle: {}",
        &out[128 * 1024..(128 * 1024 + 64).min(out.len())]
    );
}

/// The two views mark their cuts differently on purpose: the toast reads as
/// prose, the log record reads as a machine-scannable annotation.
#[test]
fn test_ui_and_log_views_use_their_own_cap_markers() {
    let input = "x".repeat(300 * 1024);

    let capture = capture_of(&[input.as_bytes()]);

    assert!(
        capture.ui().contains("bytes omitted) ..."),
        "the UI marker reads as prose: {}",
        capture.ui()
    );
    assert!(capture.log().contains("bytes omitted at cap] ..."));
}

// ── line observation ─────────────────────────────────────────────────────────

/// Collect the lines a drain over `chunks` reports.
fn observed_lines(chunks: &[&[u8]]) -> Vec<String> {
    let seen: Arc<Mutex<Vec<String>>> = Arc::new(Mutex::new(Vec::new()));
    let observer: LineObserver = {
        let seen = Arc::clone(&seen);
        Arc::new(move |line: &str| seen.lock().unwrap().push(line.to_string()))
    };
    let bytes: Vec<u8> = chunks.concat();

    drain_into(bytes.as_slice(), &Capture::new(), Some(&observer));

    let observed = seen.lock().unwrap().clone();
    observed
}

/// The observer sees complete lines, reassembled across the read boundaries
/// that split them — a live output line must never show half a word.
#[test]
fn test_observer_reassembles_lines_split_across_reads() {
    let lines = observed_lines(&[b"downloa", b"ding 40%\nunpack", b"ing\n"]);

    assert_eq!(lines, vec!["downloading 40%", "unpacking"]);
}

/// A trailing line with no newline is never reported: it may still be growing,
/// and showing a half-line as if complete is worse than showing the previous
/// one.
#[test]
fn test_observer_withholds_a_line_that_has_no_newline_yet() {
    let lines = observed_lines(&[b"complete\n", b"still-writing"]);

    assert_eq!(lines, vec!["complete"]);
}

/// Blank lines carry nothing to display; progress output is full of them.
#[test]
fn test_observer_skips_blank_lines() {
    let lines = observed_lines(&[b"a\n\n  \nb\n"]);

    assert_eq!(lines, vec!["a", "b"]);
}

/// A pathological line with no newline must not grow the buffer without bound.
#[test]
fn test_observer_caps_a_pathologically_long_line() {
    let huge = "x".repeat(100_000);

    let lines = observed_lines(&[huge.as_bytes(), b"\n"]);

    assert_eq!(lines.len(), 1);
    assert!(
        lines[0].len() <= LineSplitter::MAX_LINE,
        "line must be capped, got {} bytes",
        lines[0].len()
    );
}

/// A drain with no observer still captures — the log and UI views do not
/// depend on anyone watching.
#[test]
fn test_drain_captures_without_an_observer() {
    let capture = Capture::new();

    drain_into(b"hello\n".as_slice(), &capture, None);

    assert_eq!(capture.ui(), "hello\n");
}

// ── throttle ─────────────────────────────────────────────────────────────────

/// The first line goes out immediately, and one arriving inside the window is
/// *held* rather than dropped: it becomes the pending line, so the newest output
/// survives the rate limit instead of vanishing.
#[test]
fn test_throttle_emits_the_first_line_and_holds_the_next_in_window() {
    let throttle = Throttle::new(Duration::from_millis(250));
    let start = Instant::now();

    assert_eq!(throttle.offer("first", start), Some("first".to_string()));
    assert_eq!(
        throttle.offer("second", start + Duration::from_millis(100)),
        None
    );
    assert_eq!(
        throttle.take_pending(),
        Some("second".to_string()),
        "the line inside the window must be retained, not dropped"
    );
}

/// A burst inside one window collapses to its newest line: the display shows a
/// single line, so an older held line has no value once a newer one exists.
#[test]
fn test_throttle_keeps_only_the_newest_held_line() {
    let throttle = Throttle::new(Duration::from_millis(250));
    let start = Instant::now();
    throttle.offer("emitted", start);

    throttle.offer("held-then-superseded", start + Duration::from_millis(50));
    throttle.offer("newest", start + Duration::from_millis(100));

    assert_eq!(throttle.take_pending(), Some("newest".to_string()));
}

/// Once the window passes, emission resumes and nothing is left pending — the
/// emitted line *is* the newest, so holding it too would emit it twice.
#[test]
fn test_throttle_emits_again_after_the_window_and_clears_the_held_line() {
    let throttle = Throttle::new(Duration::from_millis(250));
    let start = Instant::now();
    throttle.offer("first", start);
    throttle.offer("held", start + Duration::from_millis(50));

    assert_eq!(
        throttle.offer("later", start + Duration::from_millis(300)),
        Some("later".to_string())
    );

    assert_eq!(
        throttle.take_pending(),
        None,
        "a line emitted after the window supersedes the held one"
    );
}

/// The window is measured from the last *emitted* line, not the last offer: a
/// stream of held lines must not extend the silence.
#[test]
fn test_throttle_window_runs_from_the_last_emission() {
    let throttle = Throttle::new(Duration::from_millis(250));
    let start = Instant::now();
    throttle.offer("first", start);

    assert_eq!(
        throttle.offer("held", start + Duration::from_millis(200)),
        None
    );

    assert_eq!(
        throttle.offer("next", start + Duration::from_millis(260)),
        Some("next".to_string()),
        "a held line must not restart the window"
    );
}

/// A pending line is taken once. Taking it twice would re-emit a line the
/// display already shows.
#[test]
fn test_throttle_yields_a_held_line_only_once() {
    let throttle = Throttle::new(Duration::from_millis(250));
    let start = Instant::now();
    throttle.offer("first", start);
    throttle.offer("held", start + Duration::from_millis(50));

    assert_eq!(throttle.take_pending(), Some("held".to_string()));

    assert_eq!(throttle.take_pending(), None);
}

/// Restarting opens the window immediately, which is what lets a new attempt's
/// first line go out even when it arrives inside the previous attempt's window.
/// It also discards a held line: that line belongs to the attempt that just
/// ended, and the new attempt is about to clear the display.
#[test]
fn test_throttle_restart_opens_the_window_and_discards_the_held_line() {
    let throttle = Throttle::new(Duration::from_millis(250));
    let start = Instant::now();
    throttle.offer("previous attempt", start);
    throttle.offer("held", start + Duration::from_millis(10));

    throttle.restart();

    assert_eq!(throttle.take_pending(), None);
    assert_eq!(
        throttle.offer("new attempt", start + Duration::from_millis(20)),
        Some("new attempt".to_string())
    );
}

// ── cut-edge erosion ─────────────────────────────────────────────────────────

/// A secret cut in half by the head cap must not survive as a fragment.
/// Redaction matches whole tokens — a prefixed secret up to the next whitespace
/// — so `nsec1qqq…` cut mid-value would still be scrubbed, but the *tail* of
/// that same value, having lost its prefix, would not be. Both cut edges drop
/// their partial token for that reason.
#[test]
fn test_capture_drops_the_partial_token_at_each_cut_edge() {
    // Positioned so the head cap lands inside the first secret and the tail cap
    // inside the second.
    let head_secret = "[REDACTED]";
    let tail_secret = "[REDACTED]";
    let input = format!(
        "{} {head_secret} {} {tail_secret} {}",
        "h".repeat(500),
        "m".repeat(4000),
        "t".repeat(1010)
    );

    let out = ui(&[input.as_bytes()]);

    assert!(out.contains("bytes omitted"), "input must exceed the cap");
    for fragment in ["nsec1head", "secretvalue"] {
        assert!(
            !out.contains(fragment),
            "a fragment of a cut token must not survive: {out}"
        );
    }
}

/// Erosion stops at the nearest whitespace, so it costs one partial token and
/// not the surrounding output — the head's earlier lines and the tail's later
/// ones are what make a truncated capture readable.
#[test]
fn test_capture_erosion_keeps_the_complete_tokens_around_the_cut() {
    let input = format!(
        "opening line
{}
cut-here-head{}cut-here-tail
{}
closing line
",
        "h".repeat(480),
        "m".repeat(4000),
        "t".repeat(980)
    );

    let out = ui(&[input.as_bytes()]);

    assert!(out.starts_with("opening line\n"), "got: {out}");
    assert!(out.ends_with("closing line\n"), "got: {out}");
}

/// A cut inside a whitespace-free run longer than the erosion window is left
/// intact. Erosion is bounded on purpose: erasing kilobytes of a single-token
/// stream — `npm` progress bars and base64 payloads both look like this — would
/// cost more diagnostics than a fragment of one could leak.
#[test]
fn test_capture_of_one_giant_token_keeps_its_cut_edges() {
    let input = "x".repeat(4000);

    let out = ui(&[input.as_bytes()]);

    assert!(out.starts_with(&"x".repeat(512)), "got: {out}");
    assert!(out.ends_with(&"x".repeat(1024)), "got: {out}");
}

/// The marker's byte count stays honest across erosion: what it names as omitted
/// must equal the input minus what is actually shown, or a reader cannot trust
/// the file to say how much is missing.
#[test]
fn test_capture_marker_counts_the_bytes_erosion_dropped() {
    let input = format!(
        "{} {} {}",
        "h".repeat(600),
        "m".repeat(4000),
        "t".repeat(1100)
    );

    let out = ui(&[input.as_bytes()]);

    let (head, rest) = out.split_once('\n').expect("a marker line");
    let (marker, tail) = rest.split_once('\n').expect("a marker line");
    let omitted: usize = marker
        .trim_start_matches("... (")
        .split_once(' ')
        .expect("a byte count")
        .0
        .parse()
        .expect("a byte count");
    assert_eq!(
        head.len() + omitted + tail.len(),
        input.len(),
        "shown + omitted must account for every input byte"
    );
}

use super::test_support::*;
use super::*;

// ── redaction ────────────────────────────────────────────────────────────────

/// Secrets that an installer echoed must not land on disk. The log is written
/// unattended, so scrubbing happens at the write, not at the read.
#[test]
fn test_log_redacts_secrets_before_writing() {
    let h = harness();
    let leak = "npm ERR! token nsec1qqqqqqqqqqsecretvalue failed";

    h.reporter.record_attempt(1, outcome("cli", false, leak));

    let log = h.log_contents();
    assert!(!log.contains("nsec1qqqqqqqqqqsecretvalue"), "got: {log}");
    assert!(log.contains("[REDACTED]"), "got: {log}");
}

/// The environment's own secrets are scrubbed too, by *name* rather than shape.
/// An install inherits Buzz's environment and installers echo it back — npm
/// prints its resolved config on an auth failure — and a token with no
/// recognizable prefix would otherwise reach the file verbatim.
#[test]
fn test_log_redacts_an_environment_secret_with_no_recognizable_prefix() {
    let secret = "[REDACTED]";
    // Set before the reporter is built: the snapshot is taken at construction.
    std::env::set_var("BUZZ_TEST_REGISTRY_TOKEN", secret);
    let h = harness();
    std::env::remove_var("BUZZ_TEST_REGISTRY_TOKEN");

    h.reporter.record_attempt(
        1,
        outcome("cli", false, &format!("npm ERR! _authToken={secret}")),
    );

    let log = h.log_contents();
    assert!(!log.contains(secret), "got: {log}");
    assert!(log.contains("[REDACTED]"), "got: {log}");
}

/// A live line carries the same scrubbing as the log record. The line is
/// rendered verbatim in the UI, so a leak there is as visible as one on disk.
#[test]
fn test_a_live_line_is_redacted_before_it_is_emitted() {
    let h = harness();

    let observer = h.reporter.line_observer().expect("an observer");
    observer("fetching with token nsec1qqqqqqqqqqleaked");

    let lines = h.lines();
    assert_eq!(lines.len(), 1);
    let line = lines[0].clone().expect("a line, not a clear signal");
    assert!(!line.contains("nsec1qqqqqqqqqqleaked"), "got: {line}");
    assert!(line.contains("[REDACTED]"), "got: {line}");
}

// ── proxy and PAT credentials ────────────────────────────────────────────────

/// A proxy URL's password is a credential, but the proxy itself is diagnostic
/// information: an install that fails behind a proxy is only debuggable if the
/// record still says which proxy it went through. So the userinfo is scrubbed
/// and the host is kept.
#[test]
fn test_proxy_userinfo_is_secret_but_the_proxy_host_is_not() {
    let secrets = secret_values_from([(
        "HTTPS_PROXY".to_string(),
        "http://corpuser:hunter2pass@proxy.example:8080".to_string(),
    )]);

    assert_eq!(secrets, vec!["corpuser:hunter2pass"]);
}

/// A proxy with no credential contributes nothing — scrubbing a bare host would
/// erase the proxy's name from every record while protecting nothing. A bare
/// username is not a credential either, and scrubbing it would delete every
/// occurrence of that word from the log.
#[test]
fn test_a_proxy_without_credentials_contributes_no_secret() {
    let secrets = secret_values_from([
        (
            "HTTP_PROXY".to_string(),
            "http://proxy.example:8080".to_string(),
        ),
        (
            "ALL_PROXY".to_string(),
            "socks5://10.0.0.1:1080".to_string(),
        ),
        (
            "HTTPS_PROXY".to_string(),
            "http://user@proxy.example:8080".to_string(),
        ),
    ]);

    assert!(secrets.is_empty(), "got: {secrets:?}");
}

/// npm reads its own `npm_config_*` aliases in preference to the conventional
/// proxy variables and prints the resolved value back, so a credential set only
/// under an alias would otherwise never enter the scrub list. npm spells them
/// in lowercase, so both cases have to classify.
#[test]
fn test_npm_proxy_aliases_are_classified_in_either_case() {
    let secrets = secret_values_from([
        (
            "npm_config_proxy".to_string(),
            "http://corpuser:lowerplain@proxy.example:8080".to_string(),
        ),
        (
            "NPM_CONFIG_PROXY".to_string(),
            "http://corpuser:upperplain@proxy.example:8080".to_string(),
        ),
        (
            "npm_config_https_proxy".to_string(),
            "http://corpuser:lowertls@proxy.example:8080".to_string(),
        ),
        (
            "NPM_CONFIG_HTTPS_PROXY".to_string(),
            "http://corpuser:uppertls@proxy.example:8080".to_string(),
        ),
    ]);

    assert_eq!(
        secrets,
        vec![
            "corpuser:lowerplain",
            "corpuser:upperplain",
            "corpuser:lowertls",
            "corpuser:uppertls",
        ]
    );
}

/// The alias carries the same userinfo-only policy as the conventional names:
/// a credential-less alias contributes nothing, so the proxy stays named in the
/// record.
#[test]
fn test_an_npm_proxy_alias_without_credentials_contributes_no_secret() {
    let secrets = secret_values_from([
        (
            "npm_config_proxy".to_string(),
            "http://proxy.example:8080".to_string(),
        ),
        (
            "NPM_CONFIG_HTTPS_PROXY".to_string(),
            "http://user@proxy.example:8080".to_string(),
        ),
    ]);

    assert!(secrets.is_empty(), "got: {secrets:?}");
}

/// The classifier and the reporter have to agree: an alias credential that
/// classifies but never reaches the scrub list still leaks. This drives the
/// reporter with exactly what the classifier produced for an alias, and asserts
/// the log and the returned step both come back clean.
#[test]
fn test_an_npm_alias_credential_is_redacted_from_the_log_and_the_returned_step() {
    let password = "hunter2pass";
    let h = harness_with_secrets(secret_values_from([(
        "npm_config_proxy".to_string(),
        format!("http://corpuser:{password}@proxy.example:8080"),
    )]));

    let returned = h.reporter.record_attempt(
        1,
        InstallOutcome {
            step: InstallStepResult {
                stderr: format!(
                    "npm ERR! proxy=http://corpuser:{password}@proxy.example:8080 tunneling failed"
                ),
                ..step("cli", false, "")
            },
            log_stdout: String::new(),
            log_stderr: format!(
                "npm config: proxy = http://corpuser:{password}@proxy.example:8080"
            ),
        },
    );

    let log = h.log_contents();
    assert!(!log.contains(password), "log leaked the password: {log}");
    assert!(
        log.contains("proxy.example"),
        "the proxy host is diagnostic and must survive: {log}"
    );
    assert!(
        !returned.stderr.contains(password),
        "the returned step leaked the password: {}",
        returned.stderr
    );
}

// ── npm's own credential settings ────────────────────────────────────────────

/// npm accepts every one of its settings as an `npm_config_*` variable, so a
/// registry client key, a basic-auth blob or a one-time password can arrive
/// under a name that carries no marker. Their whole value is the credential —
/// unlike a proxy, none of it is diagnostic — and npm spells them in lowercase.
#[test]
fn test_npm_credential_configs_are_secret_in_either_case() {
    let secrets = secret_values_from([
        (
            "npm_config_key".to_string(),
            "-----BEGIN PRIVATE KEY-----lowerkey".to_string(),
        ),
        (
            "NPM_CONFIG_KEY".to_string(),
            "-----BEGIN PRIVATE KEY-----upperkey".to_string(),
        ),
        ("npm_config__auth".to_string(), "bG93ZXJhdXRo".to_string()),
        ("NPM_CONFIG__AUTH".to_string(), "dXBwZXJhdXRo".to_string()),
        ("npm_config_otp".to_string(), "618243".to_string()),
        ("NPM_CONFIG_OTP".to_string(), "907154".to_string()),
    ]);

    assert_eq!(
        secrets,
        vec![
            "-----BEGIN PRIVATE KEY-----lowerkey",
            "-----BEGIN PRIVATE KEY-----upperkey",
            "bG93ZXJhdXRo",
            "dXBwZXJhdXRo",
            "618243",
            "907154",
        ]
    );
}

/// An unset-but-exported credential is empty, and an empty needle would match
/// everywhere. The name being exact does not make a blank value a secret.
#[test]
fn test_an_empty_npm_credential_config_contributes_no_secret() {
    let secrets = secret_values_from([
        ("NPM_CONFIG_KEY".to_string(), String::new()),
        ("npm_config_otp".to_string(), String::new()),
    ]);

    assert!(secrets.is_empty(), "got: {secrets:?}");
}

/// A private registry's URL follows the proxy policy rather than the whole-value
/// one: which registry an install talked to is exactly what a 401 or an ETIMEDOUT
/// has to be read against, so only the userinfo is the secret.
#[test]
fn test_npm_registry_userinfo_is_secret_but_the_registry_host_is_not() {
    let secrets = secret_values_from([(
        "npm_config_registry".to_string(),
        "https://builder:hunter2pass@registry.example/api/npm/".to_string(),
    )]);

    assert_eq!(secrets, vec!["builder:hunter2pass"]);
}

/// The public registry — and any private one reached with a token header rather
/// than URL credentials — contributes nothing, so the registry stays named in
/// the record.
#[test]
fn test_an_npm_registry_without_credentials_contributes_no_secret() {
    let secrets = secret_values_from([
        (
            "npm_config_registry".to_string(),
            "https://registry.npmjs.org/".to_string(),
        ),
        (
            "NPM_CONFIG_REGISTRY".to_string(),
            "https://builder@registry.example/api/npm/".to_string(),
