/// The whole point of the widening: a proxy password and a PAT that the
/// installer echoed reach neither the log nor the live line.
///
/// Both are checked through the real reporter rather than the classifier, so
/// this covers the wiring — a classifier that recognises a secret the reporter
/// never consults would still leak.
#[test]
fn test_proxy_and_pat_credentials_are_redacted_from_the_log_and_the_live_line() {
    let proxy_password = "hunter2pass";
    let pat = "[REDACTED]";
    // The classifier's own tests cover recognising these under their real
    // variable names; injecting the resulting secrets here keeps a live
    // `HTTPS_PROXY` out of the process the rest of the suite shares.
    let h = harness_with_secrets(vec![format!("corpuser:{proxy_password}"), pat.to_string()]);

    h.reporter.record_attempt(
        1,
        outcome(
            "cli",
            false,
            &format!(
                "npm ERR! proxy=http://corpuser:{proxy_password}@proxy.example authToken={pat}"
            ),
        ),
    );
    let observer = h.reporter.line_observer().expect("an observer");
    observer(&format!("cloning https://{pat}@github.com/org/repo"));

    let log = h.log_contents();
    assert!(
        !log.contains(proxy_password),
        "log leaked the proxy password: {log}"
    );
    assert!(!log.contains(pat), "log leaked the PAT: {log}");
    assert!(
        log.contains("proxy.example"),
        "the proxy host is diagnostic and must survive: {log}"
    );

    let line = h.lines().into_iter().flatten().next().expect("a live line");
    assert!(!line.contains(pat), "live line leaked the PAT: {line}");
    assert!(line.contains("[REDACTED]"), "got: {line}");
}

/// The third surface: the step returned to the frontend. `getInstallErrorMessage`
/// renders the failing step's stderr verbatim, so a secret that the log and the
/// live line both scrub would still reach the user through the error dialog.
#[test]
fn test_a_returned_step_is_redacted_before_the_frontend_renders_it() {
    let pat = "[REDACTED]";
    let h = harness_with_secrets(vec![pat.to_string()]);

    let returned = h.reporter.record_attempt(
        1,
        InstallOutcome {
            step: InstallStepResult {
                stdout: format!("configuring remote with {pat}"),
                stderr: format!("fatal: authentication failed for token {pat}"),
                hint: Some(format!("check that {pat} has the repo scope")),
                ..step("cli", false, "")
            },
            log_stdout: String::new(),
            log_stderr: String::new(),
        },
    );

    assert!(!returned.stdout.contains(pat), "got: {}", returned.stdout);
    assert!(!returned.stderr.contains(pat), "got: {}", returned.stderr);
    let hint = returned.hint.expect("a hint");
    assert!(!hint.contains(pat), "got: {hint}");
}

/// A synthesized step reaches the frontend through the other funnel, and needs
/// the same scrubbing — the managed-node prerequisite failures are built this
/// way and carry whatever the underlying command printed.
#[test]
fn test_a_synthesized_step_is_redacted_before_it_reaches_the_caller() {
    let pat = "[REDACTED]";
    let h = harness_with_secrets(vec![pat.to_string()]);
    let mut steps = Vec::new();

    h.reporter.record_step(
        &mut steps,
        InstallStepResult {
            stderr: format!("npm ERR! 401 with {pat}"),
            ..step("adapter", false, "")
        },
    );

    assert_eq!(steps.len(), 1);
    assert!(!steps[0].stderr.contains(pat), "got: {}", steps[0].stderr);
    assert!(
        steps[0].stderr.contains("[REDACTED]"),
        "got: {}",
        steps[0].stderr
    );
}

//! Test-only helper: a real second process that runs the PUBLIC auth
//! coordinator (`PkceOAuthTokenSource::acquire_with_intent`) against a shared
//! temp cache, so the auth tests can prove the *cross-process* single-flight
//! contract end-to-end rather than with two in-process handles.
//!
//! The in-process `INFLIGHT` registry coalesces same-key callers within one
//! process before they ever reach the file lock, so two `PkceOAuthTokenSource`
//! instances in one test do NOT exercise the cross-process protocol (the OS
//! advisory lock and the on-disk cache re-read). This binary is a genuine
//! second process: it contends on the same `flock`/`LockFileEx` and reads/writes
//! the same private cache file the parent coordinator does.
//!
//! The browser step is scripted (no real window): the opener drives the
//! loopback callback exactly as a real browser would, and its launch count is
//! reported back so a test can assert "exactly one browser across processes".
//!
//! Env contract (all required unless noted):
//!   AUTH_WORKER_DISCOVERY_URL   — OIDC discovery URL (the parent stub).
//!   AUTH_WORKER_CACHE_DIR       — shared cache dir (`cache_dir_override`).
//!   AUTH_WORKER_NAMESPACE       — cache namespace.
//!   AUTH_WORKER_CLIENT_ID       — OAuth client id.
//!   AUTH_WORKER_SCOPES          — comma-separated scopes.
//!   AUTH_WORKER_INTENT          — auto | userinitiated | headless.
//!   AUTH_WORKER_SCRIPT          — approve | deny | failopen.
//!   AUTH_WORKER_RESULT          — path to write the JSON outcome to.
//!   AUTH_WORKER_REJECTED        — (optional) rejected token bytes passed to
//!                                 `acquire_with_intent`; absent means no rejection.
//!   AUTH_WORKER_READY_MARKER    — (optional) written once the source is built,
//!                                 before acquisition, so the parent can release
//!                                 several workers into a genuine lock race.
//!   AUTH_WORKER_START_MARKER    — (optional) acquisition blocks until this file
//!                                 exists, so multiple workers begin together.
//!   AUTH_WORKER_LAUNCHED_MARKER — (optional) written when the browser opener
//!                                 fires (i.e. this process holds the lock and is
//!                                 mid-flow), so the parent can queue behind it.
//!   AUTH_WORKER_PROCEED_MARKER  — (optional) the scripted callback is withheld
//!                                 until this file exists, so the parent can
//!                                 confirm another process is already waiting on
//!                                 the lock before this one resolves.
//!   AUTH_WORKER_SNAPSHOT_MARKER — (optional) a file path; when set, a tracing
//!                                 layer intercepts the `acquire_leader_snapshot`
//!                                 event emitted by `auth.rs` after the attempt-
//!                                 generation snapshot is taken (and before the
//!                                 cross-process lock is acquired) and writes this
//!                                 file once. Lets the parent observe that this
//!                                 process has committed its snapshot-gen and is
//!                                 about to queue on the lock.
//!
//! Result JSON: `{ "result": "ok"|"<error_code>", "bearer": <string|null>,
//! "launches": <u64> }`.

use std::fs;
use std::io::{Read, Write};
use std::net::TcpStream;
use std::path::PathBuf;
use std::sync::atomic::{AtomicBool, AtomicU64, Ordering};
use std::sync::Arc;
use std::time::Duration;

use buzz_agent::auth::{AuthIntent, BrowserOpener, PkceOAuthConfig, PkceOAuthTokenSource};
use tracing_subscriber::layer::SubscriberExt;
use tracing_subscriber::util::SubscriberInitExt;

/// Tracing layer that writes a file once when it sees the
/// `buzz_agent::auth::acquire_leader_snapshot` event emitted by
/// `acquire_leader` immediately after the attempt-generation snapshot is fixed
/// and before the cross-process lock is acquired.  Installed only when
/// `AUTH_WORKER_SNAPSHOT_MARKER` is set, so normal test runs incur no overhead.
struct SnapshotMarkerLayer {
    path: PathBuf,
    written: AtomicBool,
}

impl<S: tracing::Subscriber> tracing_subscriber::Layer<S> for SnapshotMarkerLayer {
    fn on_event(
        &self,
        event: &tracing::Event<'_>,
        _ctx: tracing_subscriber::layer::Context<'_, S>,
    ) {
        if event.metadata().target() == "buzz_agent::auth::acquire_leader_snapshot"
            && !self.written.swap(true, Ordering::SeqCst)
        {
            let _ = fs::write(&self.path, b"snapshotted");
        }
    }
}

/// What the scripted "user" does when the coordinator opens a browser.
#[derive(Clone, Copy)]
enum Script {
    Approve,
    Deny,
    FailToOpen,
}

/// A [`BrowserOpener`] that counts launches and drives the loopback callback on
/// a background thread — the same technique as the in-crate test opener, but
/// with two optional cross-process barriers so the parent can order events:
/// `launched_marker` announces that this process holds the lock and has opened
/// the browser, and `proceed_marker` withholds the callback until the parent
/// signals it has queued another process behind the lock.
struct WorkerOpener {
    script: Script,
    calls: Arc<AtomicU64>,
    launched_marker: Option<PathBuf>,
    proceed_marker: Option<PathBuf>,
}

impl BrowserOpener for WorkerOpener {
    fn open(&self, url: &str) -> Result<(), String> {
        self.calls.fetch_add(1, Ordering::SeqCst);
        if let Some(marker) = &self.launched_marker {
            fs::write(marker, b"launched").expect("write launched marker");
        }
        let query = match self.script {
            Script::FailToOpen => return Err("no browser available".into()),
            Script::Approve => "code=scripted-code",
            Script::Deny => "error=access_denied",
        };
        let parsed = url::Url::parse(url).expect("authorize URL must parse");
        let redirect = parsed
            .query_pairs()
            .find(|(k, _)| k == "redirect_uri")
            .map(|(_, v)| v.into_owned())
            .expect("authorize URL carries redirect_uri");
        let state = parsed
            .query_pairs()
            .find(|(k, _)| k == "state")
            .map(|(_, v)| v.into_owned())
            .expect("authorize URL carries state");
        let redirect = url::Url::parse(&redirect).expect("redirect_uri must parse");
        let port = redirect.port().expect("loopback redirect carries a port");
        let request = format!(
            "GET /?{query}&state={state} HTTP/1.1\r\nHost: 127.0.0.1:{port}\r\nConnection: close\r\n\r\n"
        );
        let proceed = self.proceed_marker.clone();
        std::thread::spawn(move || {
            // Hold the callback until the parent has confirmed another process
            // is already queued behind the lock (bounded so a missing signal
            // can't wedge the test past the browser timeout).
            if let Some(marker) = proceed {
                for _ in 0..6000 {
                    if marker.exists() {
                        break;
                    }
                    std::thread::sleep(Duration::from_millis(10));
                }
            }
            if let Ok(mut sock) = TcpStream::connect(("127.0.0.1", port)) {
                let _ = sock.write_all(request.as_bytes());
                let _ = sock.flush();
                let mut discard = Vec::new();
                let _ = sock.read_to_end(&mut discard);
            }
        });
        Ok(())
    }
}

fn env(key: &str) -> String {
    std::env::var(key).unwrap_or_else(|_| panic!("{key} set"))
}

#[tokio::main]
async fn main() {
    // If the parent test set AUTH_WORKER_SNAPSHOT_MARKER, install a tracing
    // subscriber layer that fires when the coordinator emits its pre-lock
    // snapshot event and writes the marker file.
    if let Ok(marker_path) = std::env::var("AUTH_WORKER_SNAPSHOT_MARKER") {
        tracing_subscriber::registry()
            .with(SnapshotMarkerLayer {
                path: PathBuf::from(marker_path),
                written: AtomicBool::new(false),
            })
            .init();
    }

    let intent = match env("AUTH_WORKER_INTENT").as_str() {
        "auto" => AuthIntent::Auto,
        "userinitiated" => AuthIntent::UserInitiated,
        "headless" => AuthIntent::Headless,
        other => panic!("unknown AUTH_WORKER_INTENT: {other}"),
    };
    let script = match env("AUTH_WORKER_SCRIPT").as_str() {
        "approve" => Script::Approve,
        "deny" => Script::Deny,
        "failopen" => Script::FailToOpen,
        other => panic!("unknown AUTH_WORKER_SCRIPT: {other}"),
    };
    let result_path = PathBuf::from(env("AUTH_WORKER_RESULT"));
    let start_marker = std::env::var("AUTH_WORKER_START_MARKER")
        .ok()
        .map(PathBuf::from);
    let ready_marker = std::env::var("AUTH_WORKER_READY_MARKER")
        .ok()
        .map(PathBuf::from);

    let calls = Arc::new(AtomicU64::new(0));
    let opener = WorkerOpener {
        script,
        calls: calls.clone(),
        launched_marker: std::env::var("AUTH_WORKER_LAUNCHED_MARKER")
            .ok()
            .map(PathBuf::from),
        proceed_marker: std::env::var("AUTH_WORKER_PROCEED_MARKER")
            .ok()
            .map(PathBuf::from),
    };

    let cfg = PkceOAuthConfig {
        discovery_url: env("AUTH_WORKER_DISCOVERY_URL"),
        client_id: env("AUTH_WORKER_CLIENT_ID"),
        scopes: env("AUTH_WORKER_SCOPES")
            .split(',')
            .map(str::to_owned)
            .collect(),
        cache_namespace: env("AUTH_WORKER_NAMESPACE"),
        cache_dir_override: Some(PathBuf::from(env("AUTH_WORKER_CACHE_DIR"))),
    };
    let src = PkceOAuthTokenSource::new_with(cfg, Arc::new(opener)).expect("build token source");

    // Announce readiness, then wait for the parent's release so several workers
    // hit the lock together — a genuine race rather than staggered spawns.
    if let Some(marker) = &ready_marker {
        fs::write(marker, b"ready").expect("write ready marker");
    }
    if let Some(marker) = start_marker {
        for _ in 0..6000 {
            if marker.exists() {
                break;
            }
            tokio::time::sleep(Duration::from_millis(10)).await;
        }
    }

    let (result, bearer) = match src
        .acquire_with_intent(
            intent,
            std::env::var("AUTH_WORKER_REJECTED").ok().as_deref(),
        )
        .await
    {
        Ok(token) => ("ok".to_owned(), Some(token)),
        Err(e) => (e.code().to_owned(), None),
    };
    let body = serde_json::json!({
        "result": result,
        "bearer": bearer,
        "launches": calls.load(Ordering::SeqCst),
    });
    fs::write(&result_path, serde_json::to_vec(&body).unwrap()).expect("write result file");
}

use super::test_support::*;
use super::*;
use crate::commands::agent_discovery::install_capture::{drain_into, Capture};

// ── the log records history the UI does not keep ─────────────────────────────

/// Every attempt is recorded, not just the one the UI surfaces. Reproducing an
/// install failure means seeing whether attempts 1 and 2 failed the same way.
#[test]
fn test_log_records_every_attempt_not_only_the_last() {
    let h = harness();

    h.reporter
        .record_attempt(1, outcome("cli", false, "attempt-one-output"));
    h.reporter
        .record_attempt(2, outcome("cli", false, "attempt-two-output"));

    let log = h.log_contents();
    assert!(log.contains("attempt-one-output"), "got: {log}");
    assert!(log.contains("attempt-two-output"), "got: {log}");
    assert!(
        log.contains("attempt=1") && log.contains("attempt=2"),
        "got: {log}"
    );
}

/// A first attempt that printed a huge amount must not push later records out of
/// the file. Records are capped individually by the log-scale capture that
/// produced them, so the run's total is bounded by steps × attempts × cap rather
/// than by one runaway attempt.
///
/// The flood goes through a real [`Capture`] rather than straight into the
/// record, so this exercises the cap that actually bounds a record.
#[test]
fn test_first_attempt_overflow_does_not_erase_later_records() {
    let h = harness();
    // Through the real drain, so the record is bounded by the cap that bounds a
    // production record rather than by a string this test chose.
    let capture = Capture::new();
    drain_into(vec![b'F'; 4 * 1024 * 1024].as_slice(), &capture, None);

    h.reporter
        .record_attempt(1, outcome("cli", false, &capture.log()));
    h.reporter
        .record_attempt(2, outcome("cli", false, "second-attempt-detail"));
    h.reporter.record_step(
        &mut Vec::new(),
        step("verify", false, "verification-detail"),
    );

    let log = h.log_contents();
    assert!(
        log.contains("bytes omitted at cap"),
        "the flooded record must be marked as cut"
    );
    assert!(
        log.contains("second-attempt-detail"),
        "a later attempt must survive an earlier flood"
    );
    assert!(
        log.contains("verification-detail"),
        "the synthesized step explaining the failure must survive too"
    );
    assert!(
        log.len() < 4 * 1024 * 1024,
        "4MiB of first-attempt output must not reach the file, got {} bytes",
        log.len()
    );
}

/// A step Buzz synthesizes — a failed prerequisite, or post-install
/// verification — reaches the log as well as the UI. `record_step` is the only
/// path that guarantees this, which is why callers use it instead of
/// `steps.push`.
#[test]
fn test_recording_a_synthesized_step_logs_it_and_keeps_it_for_the_ui() {
    let h = harness();
    let mut steps = Vec::new();

    h.reporter
        .record_step(&mut steps, step("verify", false, "still-not-usable"));

    assert_eq!(steps.len(), 1, "the UI must still receive the step");
    assert!(h.log_contents().contains("still-not-usable"));
}

// ── one file per run ─────────────────────────────────────────────────────────

/// A run opens with a header naming the runtime and the environment the run
/// happened in, so a file holding one run of several steps is identifiable as
/// that run rather than a stream of records — and a failure report says which
/// app version and OS produced it without a second round trip to the user.
#[test]
fn test_a_run_opens_with_a_header_naming_the_runtime_app_version_and_os() {
    let h = harness();
    let log = h.log_contents();

    assert!(
        log.starts_with(&format!(
            "=== install run runtime=goose app={TEST_APP_VERSION} os={} started=",
            std::env::consts::OS
        )),
        "got: {log}"
    );
}

/// A new run does not append to the previous run's file: it starts a fresh one
/// and keeps the previous as `.1`. Reading a log has to mean reading one run —
/// records accumulated across runs are indistinguishable from retries within
/// one.
#[test]
fn test_a_new_run_starts_a_fresh_file_and_keeps_the_previous_as_dot_one() {
    let first = harness();
    first
        .reporter
        .record_attempt(1, outcome("cli", false, "previous-run-output"));
    let previous = first.log.clone();
    let dir = first._dir;
    drop(first.reporter);

    let second = harness_at(Some(dir));
    second
        .reporter
        .record_attempt(1, outcome("cli", false, "current-run-output"));

    let log = second.log_contents();
    assert!(log.contains("current-run-output"), "got: {log}");
    assert!(
        !log.contains("previous-run-output"),
        "the new run's file must not carry the previous run's records: {log}"
    );
    let rotated = std::fs::read_to_string(previous.with_extension("log.1")).expect("read .1");
    assert!(
        rotated.contains("previous-run-output"),
        "the previous run must remain readable as .1: {rotated}"
    );
}

/// Each executed attempt records how long it ran. A 15-minute ceiling is only
/// diagnosable if the file says which attempt consumed the time.
#[test]
fn test_an_executed_attempt_records_its_own_duration() {
    let h = harness();

    h.reporter.start_attempt();
    h.reporter.record_attempt(1, outcome("cli", true, "done"));
    h.reporter
        .record_step(&mut Vec::new(), step("verify", true, ""));

    let log = h.log_contents();
    assert!(
        log.contains("attempt=1") && log.contains("elapsed=0."),
        "an executed attempt must carry its duration: {log}"
    );
    assert!(
        log.contains("attempt=- ") && log.contains("elapsed=-"),
        "a synthesized step never ran, so it has no duration: {log}"
    );
}

