    write_log_in(dir.path(), &format!("{PUBKEY_A}__cafe.log"), 5);

    assert_eq!(
        super::newest_agent_log_in_dir(dir.path(), PUBKEY_A),
        Some(dir.path().join(format!("{PUBKEY_A}__cafe.log")))
    );
}

