    let cases = [
        ("content", "x".repeat(2048), vec![h()]),
        (
            "tag value",
            String::new(),
            vec![
                h(),
                Tag::parse(["e".to_string(), "x".repeat(2048)]).unwrap(),
            ],
        ),
        (
