#[tokio::test]
#[ignore = "requires Postgres and Redis"]
async fn fenced_community_typing_is_rejected() {
    let f = Fixture::new().await;
    // Over HTTP a quiescing community's host no longer binds (404), so the
    // fence only matters when quiescing starts after the request has bound its
    // tenant. Reproduce that order: bind first, then quiesce, then publish.
    let tenant = crate::tenant::bind_community(&f.state.db, &f.host)
        .await
        .unwrap();
    // Enter the deletion executor's transaction scope in this disposable
    // fixture; the DB rejects unfenced ad-hoc state changes.
    let mut tx = f.pool.begin().await.unwrap();
    sqlx::query("SELECT set_config('buzz.deletion_executor_community', $1, true), set_config('buzz.deletion_fence_generation', '0', true)")
        .bind(f.community.to_string())
        .execute(&mut *tx)
        .await
        .unwrap();
    sqlx::query("UPDATE communities SET deletion_state = 'quiescing' WHERE id = $1")
        .bind(f.community.as_uuid())
        .execute(&mut *tx)
        .await
        .unwrap();
    tx.commit().await.unwrap();

    let pubsub = f.subscribe_channel().await;

    let err = crate::handlers::event::publish_http_typing(
        &f.state,
        &tenant,
        f.typing(&f.member, Some(f.channel)),
        f.member.public_key(),
    )
    .await
    .unwrap_err();
    assert!(
        matches!(&err, IngestError::Rejected(msg) if msg == "restricted: community writes are fenced"),
        "{err:?}"
    );
    assert_nothing_published(pubsub, "fenced typing indicator").await;
}

async fn assert_nothing_published(pubsub: redis::aio::PubSub, what: &str) {
    use futures::StreamExt;
    let mut messages = pubsub.into_on_message();
    assert!(
        tokio::time::timeout(std::time::Duration::from_millis(500), messages.next())
            .await
            .is_err(),
        "{what} must not be published"
    );
}

use axum::{
    body::{to_bytes, Body},
    http::{Request, StatusCode},
};
use base64::Engine;
use nostr::{EventBuilder, Keys, Kind, Tag};
use serde_json::{json, Value};
use sha2::{Digest, Sha256};
use std::sync::Arc;
use tower::ServiceExt;

fn proof(key: &Keys, host: &str, path: &str, method: &str, body: Option<&[u8]>) -> String {
    let mut tags = vec![
        Tag::parse(["u", &format!("https://{host}{path}")]).unwrap(),
        Tag::parse(["method", method]).unwrap(),
        Tag::parse(["nonce", &uuid::Uuid::new_v4().to_string()]).unwrap(),
    ];
    if let Some(body) = body {
        tags.push(Tag::parse(["payload", &hex::encode(Sha256::digest(body))]).unwrap());
    }
    let event = EventBuilder::new(Kind::Custom(27235), "")
        .tags(tags)
        .sign_with_keys(key)
        .unwrap();
    format!(
        "Nostr {}",
        base64::engine::general_purpose::STANDARD.encode(serde_json::to_vec(&event).unwrap())
    )
}

async fn request(
    state: Arc<crate::state::AppState>,
    host: &str,
    path: &str,
    method: &str,
    auth: Option<&str>,
    body: &[u8],
) -> (StatusCode, Value) {
    let mut req = Request::builder()
        .method(method)
        .uri(path)
        .header("host", host);
    if let Some(auth) = auth {
        req = req.header("authorization", auth);
    }
    let response = crate::router::build_router(state)
        .oneshot(req.body(Body::from(body.to_vec())).unwrap())
        .await
        .unwrap();
    let status = response.status();
    assert_eq!(
        response.headers().get("cache-control").unwrap(),
        "private, no-store"
    );
    let bytes = to_bytes(response.into_body(), 1024 * 1024).await.unwrap();
    (status, serde_json::from_slice(&bytes).unwrap())
}

/// Start a reader's account before any fixture arrival. Nothing counts as
/// unread until an account starts.
async fn start_before_everything(
    state: &crate::state::AppState,
    community: buzz_core::CommunityId,
    key: &Keys,
) {
    sqlx::query(
        "INSERT INTO personal_read_accounts (community_id,actor,started_at)
         VALUES ($1,$2,'1900-01-01T00:00:00Z')",
    )
    .bind(community.as_uuid())
    .bind(key.public_key().to_bytes().as_slice())
    .execute(state.db.pool())
    .await
    .unwrap();
}

#[tokio::test]
#[ignore = "requires Postgres"]
async fn accessory_router_signed_url_body_replay_and_actor_boundary() {
    let fixture = crate::api::bridge::postgres_tests::bridge_handler_test_state()
        .await
        .unwrap();
    let mut state = (*fixture).clone();
    let config = Arc::make_mut(&mut state.config);
    config.require_auth_token = true;
    config.require_relay_membership = true;
    config.buzz_v1_enabled = true;
    state.nip98_replay = Arc::new(buzz_pubsub::RedisNip98ReplayGuard::new(
        state.redis_pool.clone(),
    ));
    let state = Arc::new(state);
    let host = format!("bff-{}.local", uuid::Uuid::new_v4());
    let community = state
        .db
        .ensure_configured_community(&host)
        .await
        .unwrap()
        .id;
    let actor = Keys::generate();
    let other = Keys::generate();
    let path = "/buzz/v1/me/sidebar?limit=1";
    let auth = proof(&actor, &host, path, "GET", None);
    assert_eq!(
        request(state.clone(), &host, path, "GET", Some(&auth), b"")
            .await
            .0,
        StatusCode::FORBIDDEN
    );
    for key in [&actor, &other] {
        state
            .db
            .add_relay_member(
                community,
                &key.public_key().to_hex(),
                "member",
                None,
                &nostr::Keys::generate(),
            )
            .await
            .map(|write| write.outcome)
            .unwrap();
    }
    assert_eq!(
        request(state.clone(), &host, path, "GET", None, b"")
            .await
            .0,
        StatusCode::UNAUTHORIZED
    );
    let wrong_query = proof(&actor, &host, "/buzz/v1/me/sidebar?limit=2", "GET", None);
    assert_eq!(
        request(state.clone(), &host, path, "GET", Some(&wrong_query), b"")
            .await
            .0,
        StatusCode::UNAUTHORIZED
    );
    let wrong_host = proof(&actor, "other.invalid", path, "GET", None);
    assert_eq!(
        request(state.clone(), &host, path, "GET", Some(&wrong_host), b"")
            .await
            .0,
        StatusCode::UNAUTHORIZED
    );
    let auth = proof(&actor, &host, path, "GET", None);
    let accepted = request(state.clone(), &host, path, "GET", Some(&auth), b"").await;
    assert_eq!(accepted.0, StatusCode::OK, "{}", accepted.1);
    assert_eq!(
        request(state.clone(), &host, path, "GET", Some(&auth), b"")
            .await
            .0,
        StatusCode::UNAUTHORIZED
    );
    // Targeted refresh is exclusive with paging and bounded to unique IDs.
    let id = uuid::Uuid::new_v4();
    let many = (0..21)
        .map(|_| uuid::Uuid::new_v4().to_string())
        .collect::<Vec<_>>()
        .join(",");
    for (query, status) in [
        (format!("channel_ids={id}"), StatusCode::OK),
        (format!("channel_ids={id},{id}"), StatusCode::BAD_REQUEST),
        (format!("channel_ids={id}&limit=1"), StatusCode::BAD_REQUEST),
        (
            format!("channel_ids={id}&cursor={id}"),
            StatusCode::BAD_REQUEST,
        ),
        ("channel_ids=".into(), StatusCode::BAD_REQUEST),
        ("channel_ids=not-a-uuid".into(), StatusCode::BAD_REQUEST),
        (format!("channel_ids={many}"), StatusCode::BAD_REQUEST),
    ] {
        let path = format!("/buzz/v1/me/sidebar?{query}");
        let auth = proof(&actor, &host, &path, "GET", None);
        let (got, body) = request(state.clone(), &host, &path, "GET", Some(&auth), b"").await;
        assert_eq!(got, status, "{query}: {body}");
        if status == StatusCode::OK {
            assert_eq!(body["channels"], json!([]), "unjoined ID is simply absent");
            assert!(body["next_cursor"].is_null());
        }
    }
    let channel = state
        .db
        .create_channel(
            community,
            "boundary",
            buzz_db::channel::ChannelType::Stream,
            buzz_db::channel::ChannelVisibility::Open,
            None,
            &actor.public_key().to_bytes(),
            None,
        )
        .await
        .unwrap()
        .id;
    let event = EventBuilder::new(Kind::Custom(9), "read by one signer only")
        .sign_with_keys(&Keys::generate())
        .unwrap();
    state
        .db
        .insert_event(community, &event, Some(channel))
        .await
        .unwrap();
    state
        .db
        .add_member(
            community,
            channel,
            &other.public_key().to_bytes(),
            buzz_db::channel::MemberRole::Member,
            None,
        )
        .await
        .unwrap();
    let write_path = "/buzz/v1/me/read-state";
    let body = serde_json::to_vec(&json!({"intents":[{"type":"mark_through",
        "target":{"channel_id":channel},"message_id":event.id.to_hex()}]}))
    .unwrap();
    let missing_hash = proof(&actor, &host, write_path, "POST", None);
    assert_eq!(
        request(
            state.clone(),
            &host,
            write_path,
            "POST",
            Some(&missing_hash),
            &body
        )
        .await
        .0,
        StatusCode::UNAUTHORIZED
    );
    let wrong_hash = proof(&actor, &host, write_path, "POST", Some(b"{}"));
    assert_eq!(
        request(
            state.clone(),
            &host,
            write_path,
            "POST",
            Some(&wrong_hash),
            &body
        )
        .await
        .0,
        StatusCode::UNAUTHORIZED
    );
    let auth = proof(&actor, &host, write_path, "POST", Some(&body));
    let applied = request(state.clone(), &host, write_path, "POST", Some(&auth), &body).await;
    assert_eq!(applied.0, StatusCode::OK, "{}", applied.1);
    assert_eq!(applied.1["outcomes"][0]["status"], "applied");
    // The frontier belongs to the signer alone.
    let path = format!("/buzz/v1/me/sidebar?channel_ids={channel}");
    start_before_everything(&state, community, &other).await;
    for (key, unread, read_through) in [
        (&actor, false, json!(event.id.to_hex())),
        (&other, true, Value::Null),
    ] {
        let auth = proof(key, &host, &path, "GET", None);
        let page = request(state.clone(), &host, &path, "GET", Some(&auth), b"").await;
        assert_eq!(page.0, StatusCode::OK, "{}", page.1);
        assert_eq!(page.1["channels"][0]["unread"], unread, "{}", page.1);
        assert_eq!(page.1["channels"][0]["read_through_id"], read_through);
    }
}

#[tokio::test]
#[ignore = "requires Postgres"]
async fn accessory_batch_outcomes_are_independent_and_return_applied_rows() {
    let fixture = crate::api::bridge::postgres_tests::bridge_handler_test_state()
        .await
        .unwrap();
    let mut state = (*fixture).clone();
    Arc::make_mut(&mut state.config).buzz_v1_enabled = true;
    let state = Arc::new(state);
    let host = format!("bff-batch-{}.local", uuid::Uuid::new_v4());
    let community = state
        .db
        .ensure_configured_community(&host)
        .await
        .unwrap()
        .id;
    let actor = Keys::generate();
    let create = |name: &'static str, owner: &Keys| {
        let (state, owner) = (state.clone(), owner.public_key().to_bytes());
        async move {
            state
                .db
                .create_channel(
                    community,
                    name,
                    buzz_db::channel::ChannelType::Stream,
                    buzz_db::channel::ChannelVisibility::Open,
                    None,
                    &owner,
                    None,
                )
                .await
                .unwrap()
                .id
        }
    };
    let channel = create("joined", &actor).await;
    // Open, so marking it applies, but never joined.
    let unjoined = create("open, not joined", &Keys::generate()).await;
    let post = |channel| {
        let state = state.clone();
        async move {
            let event = EventBuilder::new(Kind::Custom(9), "read state")
                .sign_with_keys(&Keys::generate())
                .unwrap();
            state
                .db
                .insert_event(community, &event, Some(channel))
                .await
                .unwrap();
            event.id.to_hex()
        }
    };
    let (event, elsewhere) = (post(channel).await, post(unjoined).await);
    start_before_everything(&state, community, &actor).await;
    let path = format!("/buzz/v1/me/sidebar?channel_ids={channel}");
    let auth = proof(&actor, &host, &path, "GET", None);
    let result = request(state.clone(), &host, &path, "GET", Some(&auth), b"").await;
    assert_eq!(result.0, StatusCode::OK, "{}", result.1);
    let unread = json!({"channel_id":channel,"unread":true,"mentions":0,
        "read_through_id":null,"latest_id":event,"threads":[]});
    assert_eq!(result.1["channels"], json!([unread]));
    let write_path = "/buzz/v1/me/read-state";
    let body = serde_json::to_vec(&json!({"intents":[
        {"type":"unknown"},
        {"type":"mark_through","target":{"channel_id":uuid::Uuid::new_v4()},"message_id":event},
        {"type":"mark_through","target":{"channel_id":channel},"message_id":event},
        {"type":"mark_through","target":{"channel_id":channel},"message_id":"not an event id"},
        {"type":"mark_through","target":{"channel_id":channel},"message_id":event},
        {"type":"mark_through","target":{"channel_id":unjoined},"message_id":elsewhere}
    ]}))
    .unwrap();
    let auth = proof(&actor, &host, write_path, "POST", Some(&body));
    let result = request(state.clone(), &host, write_path, "POST", Some(&auth), &body).await;
    assert_eq!(result.0, StatusCode::OK, "{}", result.1);
    assert_eq!(
        result.1["outcomes"],
        json!([{"status":"invalid"},{"status":"blocked"},{"status":"applied"},
            {"status":"invalid"},{"status":"applied"},{"status":"applied"}])
    );
    // One updated row per applied channel; the blocked and the unjoined
    // channels have none.
    let read = json!({"channel_id":channel,"unread":false,"mentions":0,
        "read_through_id":event,"latest_id":event,"threads":[]});
    assert_eq!(result.1["channels"], json!([read]));

    // The removed context read is not served, however well signed.
    let targets = json!([{"target":{"channel_id":channel},"message_ids":[event]}]);
    let targets: String = targets
        .to_string()
        .bytes()
        .map(|b| format!("%{b:02X}"))
        .collect();
    let path = format!("/buzz/v1/me/read-state?targets={targets}");
    let response = crate::router::build_router(state.clone())
        .oneshot(
            Request::builder()
                .uri(&path)
                .header("host", &host)
                .header("authorization", proof(&actor, &host, &path, "GET", None))
                .body(Body::empty())
                .unwrap(),
        )
        .await
        .unwrap();
    assert_ne!(response.status(), StatusCode::OK);
}

